% Detlog code generated by detlog2 from examples/sample_program.pl
% No cuts and no choicepoints: every predicate succeeds exactly once and
% returns its answer packet (rows and out(Text) items) in its last argument.
% Run it with: detlog2 run --det FILE 'p__cp(Args..., Packet)'
%
% cut_to_if_commit(safe_cut/1, clause 1)
% predicate_to_packet(det_sum/2, 2 clauses)
% predicate_to_packet(nondet_member/2, 1 clauses)
% member_to_member_cp
% facts_to_member_cp(multi_fact/1, 3 facts)
% predicate_to_packet(if_then_else/2, 1 clauses)
% predicate_to_packet(safe_cut/1, 1 clauses)
% predicate_to_packet(side_effect/1, 1 clauses)
% proof accepted: 14 steps, 14 clauses justified

det_sum__cp(A1, A2, Rows) :-
    det_sum__cp_c1([A1, A2], R1),
    det_sum__cp_c2([A1, A2], R2),
    rows_concat([R1, R2], Rows).

det_sum__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [[], 0]),
        Rows = [[[], 0]],
        Rows = []
    ).

det_sum__cp_c2(Args, Rows) :-
    if_commit(
        copy_term(Args, [[H|T], S]),
        (   det_sum__cp(T, Rest, Packet),
            splice_extend(Packet, [H, T, S, Rest], [T, Rest], R),
            det_sum_c2__cp_1(R, Env),
            splice_extend(Env, [[H|T], S], [H, T, S, Rest], Rows)
        ),
        Rows = []
    ).

det_sum_c2__cp_1([], []).
det_sum_c2__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [H, T, S, Rest]),
            if_commit(
                S is H + Rest,
                Out1 = [[H, T, S, Rest]],
                Out1 = []
            )
        )
    ),
    det_sum_c2__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

nondet_member__cp(A1, A2, Rows) :-
    nondet_member__cp_c1([A1, A2], Rows).

nondet_member__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X, List]),
        (   member_cp(P, List),
            cp_rows(P, PRows),
            splice_extend(PRows, [X, List], [X], Env),
            splice_extend(Env, [X, List], [X, List], Rows)
        ),
        Rows = []
    ).

multi_fact__cp(A1, Rows) :-
    member_cp(P, [[a], [b], [b]]),
    cp_filter(P, [A1], Rows).

if_then_else__cp(A1, A2, Rows) :-
    if_then_else__cp_c1([A1, A2], Rows).

if_then_else__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X, Y]),
        (   if_commit(
                X > 0,
                if_commit(
                    Y = pos,
                    Env = [[X, Y]],
                    Env = []
                ),
                if_commit(
                    Y = nonpos,
                    Env = [[X, Y]],
                    Env = []
                )
            ),
            splice_extend(Env, [X, Y], [X, Y], Rows)
        ),
        Rows = []
    ).

safe_cut__cp(A1, Rows) :-
    safe_cut__cp_c1([A1], Rows).

safe_cut__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A1]),
        (   if_commit(
                (   A1 = X,
                    X > 0
                ),
                Env = [[A1, X, V1]],
                if_commit(
                    A1 = V1,
                    Env = [[A1, X, V1]],
                    Env = []
                )
            ),
            splice_extend(Env, [A1], [A1, X, V1], Rows)
        ),
        Rows = []
    ).

side_effect__cp(A1, Rows) :-
    side_effect__cp_c1([A1], Rows).

side_effect__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X]),
        (   effect_text(writeln(X), Text),
            Env = [out(Text), [X]],
            splice_extend(Env, [X], [X], Rows)
        ),
        Rows = []
    ).
